def rust(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def declare(codes, indent, qualified=False, statement=None, awaited=False):
    label = "semio_framework_plugin::LocalizedLabel" if qualified else "LocalizedLabel"
    out = ""
    for code in codes:
        en, de = TEXTS[code]
        call = f".fault({rust(code)}, {label}::native({rust(en)}, {rust(de)}))"
        out += f"{indent}{statement} = {statement}{call};\n" if statement else f"{indent}{call}{'.await' if awaited else ''}\n"
    return out
